<div class="grid gap-5 sm:grid-cols-2"><label class="block"><span class="text-sm font-semibold">Nama</span><input name="name" value="{{ old('name', $user->name ?? '') }}" required class="mt-2 w-full rounded-xl border-stone-200"></label><label class="block"><span class="text-sm font-semibold">Email</span><input type="email" name="email" value="{{ old('email', $user->email ?? '') }}" required class="mt-2 w-full rounded-xl border-stone-200"></label><label class="block"><span class="text-sm font-semibold">Password {{ isset($user) ? '(kosongkan jika tidak diubah)' : '' }}</span><input type="password" name="password" {{ isset($user) ? '' : 'required' }} class="mt-2 w-full rounded-xl border-stone-200"></label><label class="block"><span class="text-sm font-semibold">Konfirmasi password</span><input type="password" name="password_confirmation" {{ isset($user) ? '' : 'required' }} class="mt-2 w-full rounded-xl border-stone-200"></label><label class="block"><span class="text-sm font-semibold">Peran</span><select name="role" class="mt-2 w-full rounded-xl border-stone-200"><option value="customer" @selected(old('role', $user->role ?? '') === 'customer')>Customer</option><option value="admin" @selected(old('role', $user->role ?? '') === 'admin')>Admin</option></select></label><label class="block"><span class="text-sm font-semibold">Telepon</span><input name="phone" value="{{ old('phone', $user->phone ?? '') }}" class="mt-2 w-full rounded-xl border-stone-200"></label></div><button class="mt-6 rounded-xl bg-stone-900 px-5 py-3 font-semibold text-white hover:bg-amber-700">Simpan pengguna</button>
